import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";
import { caret } from "../../../icons";
import { addConstructedStyle } from "../../utils/browser";
import { generateShortID } from "../../utils/function-helper";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { getCssRulesForSentimentButton } from "../../utils/sentiments";
import { hasSlot } from "../../utils/slot";
import { color } from "../../utils/token";

/**
 * @since 0.0.10
 * @status stable
 *
 * @data-testid HbrButton-button - The internal native button element rendered by the component.
 *
 * @description Buttons communicate actions that users can take. They are typically placed throughout your UI, in places like modals, forms, cards, toolbars etc.
 *
 * @slot - The button's label.
 * @slot prefix - Used to prepend an icon or similar element to the button.
 * @slot suffix - Used to append an icon or similar element to the button.
 *
 * @part base - The component's base wrapper.
 * @part text - The component's base wrapper for the text button.
 * @part error - The component's base wrapper with the error state.
 * @part prefix - The prefix container.
 * @part label - The button's label.
 * @part suffix - The suffix container.
 * @part caret - The button's caret.
 */

@Component({
	tag: "hbr-button",
	styleUrl: "button.scss",
	shadow: true,
})
export class Button {
	button?: HTMLButtonElement;
	sheet: CSSStyleSheet = new CSSStyleSheet();
	sentimentSheet: CSSStyleSheet = new CSSStyleSheet();
	spinner?: boolean;

	@Element() host!: HTMLHbrButtonElement;

	@State() hasFocus = false;
	@State() hasLabel = false;
	@State() hasPrefix = false;
	@State() hasSuffix = false;
	@State() splitPosition?: "left" | "right";
	@State() tooltipId = `tooltip-${generateShortID()}`;

	/** The button's color scheme. "danger" is used to indicate destructive actions. */
	@Prop({ reflect: true, mutable: true }) sentiment?:
		| "default"
		| "neutral"
		| "interact"
		| "admin"
		| "success"
		| "warning"
		| "danger"
		| "info"
		| string;

	/** The button styles. Primary buttons use "fill" (default), secondary buttons use "outline" and tertiary buttons use "text". "context" button fits into current context, inherits color styles from parent. */
	@Prop({ reflect: true }) variant?: "fill" | "outline" | "text" | "context";

	/** The button's size. */
	@Prop({ reflect: true }) size: "xsmall" | "small" | "medium" | "large" =
		"medium";

	/** Set to true to draw the button with a caret for use with dropdowns, popovers, etc. */
	@Prop({ reflect: true }) caret = false;

	/** Set to true to disable - disable the primary action button once it has been clicked and the action is being performed to prevent duplication of the action with a second click. */
	@Prop({ reflect: true, mutable: true }) disabled = false;

	/** Set to true to draw the button in a loading state. */
	@Prop({ reflect: true }) loading = false;

	/** Set to true to draw a pill-style button with rounded edges. */
	@Prop({ reflect: true }) pill = false;

	/** Set to true to draw a circle button. */
	@Prop({ reflect: true }) circle = false;

	/** [deprecated] use type=submit */
	@Prop({ reflect: true }) submit = false;

	/** Indicates if error state */
	@Prop({ reflect: true }) error = false;

	/** Floating action button */
	@Prop({ reflect: true }) floating = false;

	/** [deprecated] use type=submit */
	@Prop({ reflect: true }) requestSubmit = false;

	/**
	 * The type of button. When the type is `submit`, the button will submit the surrounding form. Note that the default
	 * value is `button` instead of `submit`, which is opposite of how native `<button>` elements behave.
	 */
	@Prop({ reflect: true }) type: "button" | "submit" = "button";

	/** An optional name for the button */
	@Prop() name?: string;

	/** An optional value for the button. */
	@Prop() value?: string;

	/** The no padding on tertiary text link button. */
	@Prop({ reflect: true }) noPadding?: boolean;

	/** aria-haspopup */
	@Prop() ariahaspopup?: string;

	/** aria-expanded */
	@Prop() ariaexpanded?: string;

	/** aria-label */
	@Prop() arialabel?: string;

	/** aria-controls */
	@Prop() ariacontrols?: string;

	/** role */
	@Prop({ reflect: true }) ariarole?: string;
	/** aria-pressed */
	@Prop() ariapressed?: string;

	/** Attributes related to screen readers. */
	@Prop() aria?: {
		label?: string;
		haspopup?: boolean;
		expanded?: string | boolean;
		controls?: string;
		role?: string;
		pressed?: boolean;
	};

	/** tabindex */
	@Prop() tabidx?: string;

	/** Tooltip content if the button serves as a tooltip reference. */
	@Prop({ reflect: true }) tooltip?: string;

	/** Emitted when the button loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur!: EventEmitter<void>;

	/** Emitted when the button gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus!: EventEmitter<void>;

	buttonGroup = false;
	visibilityHidden = false;

	connectedCallback() {
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handlePointerDown = this.handlePointerDown.bind(this);
		this.handleClick = this.handleClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.buttonGroup = !!this.host.closest("hbr-button-group");
		this.visibilityHidden = this.containVisuallyHidden();
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	/** Sets focus on the button. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.button?.focus(options);
	}

	/** Removes focus from the button. */
	@Method()
	async removeFocus() {
		this.button?.blur();
	}

	/** Sets the split button position when managed by an internal button group. */
	@Method()
	async setSplitPosition(splitPosition?: "left" | "right") {
		this.splitPosition = splitPosition;
	}

	handleSlotChange() {
		this.hasLabel = this.visibilityHidden ? false : hasSlot(this.host);
		this.hasPrefix = hasSlot(this.host, "prefix");
		this.hasSuffix = hasSlot(this.host, "suffix");

		/** make sure to set sentiment's default to interact for the loading buttons due to the spinning icon color */
		this.spinner =
			!this.loading &&
			this.hasPrefix &&
			!!this.host.querySelector("hbr-spinner");

		if (this.loading || this.spinner) {
			this.disabled = true;
			if (!this.sentiment) {
				this.sentiment = "interact";
			}
		}
	}

	containVisuallyHidden() {
		const { children } = this.host;
		if (children.length) {
			const el = Array.from(children)[0] as HTMLElement;
			const tagName = el.tagName.toLowerCase();
			if (tagName === "hbr-visually-hidden") {
				return true;
			}
		}
		return false;
	}

	handleBlur(event: FocusEvent) {
		this.hasFocus = false;
		this.hbrBlur.emit();
		void event;
		this.host.removeAttribute("data-focused");
	}

	handleFocus(event: FocusEvent) {
		this.hasFocus = true;
		this.hbrFocus.emit();

		const target = event.target as HTMLElement | null;
		const isFocusVisible = !!target?.matches?.(":focus-visible");

		if (isFocusVisible) {
			this.host.setAttribute("data-focused", "true");
		} else {
			this.host.removeAttribute("data-focused");
		}
	}

	handlePointerDown() {
		if (this.host.hasAttribute("data-focused")) {
			this.button?.blur();
		}
	}

	handleClick(event: MouseEvent) {
		if (this.disabled || this.loading) {
			event.preventDefault();
			event.stopPropagation();
		} else {
			if (this.requestSubmit || this.type === "submit") {
				this.host.closest("form")?.requestSubmit();
			}
		}
	}

	render() {
		const { disabled, loading, size, circle, sentiment, variant, arialabel } =
			this;
		let part = "base";
		if (this.error) part += " error";

		let _sentiment = sentiment;
		let _variant = variant;
		if (!_sentiment) {
			if (!this.buttonGroup) {
				_sentiment = "interact";
			} else {
				_sentiment = "default";
			}
		}
		if (!_variant) {
			if (!this.buttonGroup) {
				_variant = "fill";
			} else {
				_variant = "outline";
			}
		}

		const iconButton = this.circle && this.host.querySelector("hbr-icon");
		// truthy only when hbr-icon is present in the default slot and not in suffix, prefix, etc
		const iconLabelButton = this.host.querySelector("hbr-icon:not([slot])");

		const btnCls: Record<string, boolean> = {
			button: true,

			// Sizes
			"button--xsmall": size === "xsmall",
			"button--small": size === "small",
			"button--medium": size === "medium",
			"button--large": size === "large",
			// Modifiers
			"button--caret": this.caret,
			"button--circle": circle,
			"button--disabled": disabled,
			"button--focused": this.hasFocus,
			"button--loading": loading,
			"button--pill": this.pill,
			"button--standard": _variant !== "outline",
			"button--outline": _variant === "outline",
			"button--has-label": this.hasLabel,
			"button--has-prefix": this.hasPrefix,
			"button--has-suffix": this.hasSuffix,
			"button--no-padding": !!this.noPadding,
			"button--icon-button": !!iconButton,
			"button--icon-label-button": !!iconLabelButton,
			"button--floating": this.floating,
			"split--left": this.splitPosition === "left",
			"split--right": this.splitPosition === "right",

			// State
			"button--error": this.error,
		};
		btnCls[`button--${_sentiment}`] = !!this.sentiment || !!_sentiment;
		btnCls[`button--${_variant}`] = !!this.variant || !!_variant;

		let ariaLabel = "";
		if (!this.visibilityHidden) {
			if (arialabel) {
				ariaLabel = arialabel;
			}
		}

		if (this.host) {
			if (this.buttonGroup && _sentiment === "default") {
				this.sheet.replaceSync(`
					:host {
						--bg-color: none;
						--border-color: var(--base-border-medium-default);
						--border-color-hover: var(--control-border-weak-disabled);
						--bg-color-hover: var(--base-bg-weak-hover);
						--label-color-hover: var(--base-text-default);
					}
				`);
			} else if (
				![
					"interact",
					"danger",
					"success",
					"warning",
					"info",
					"positive",
					"negative",
				].includes(_sentiment)
			) {
				// Non-Magnetic and custom sentiments
				this.sheet.replaceSync(`
					:host {
						--bg-color: ${
							_sentiment === "default"
								? `${
										disabled
											? "var(--base-bg-strong-disabled)"
											: color("neutral", "bg")
								  }`
								: _variant === "fill"
								  ? color(
											_sentiment,
											"",
											"",
											loading ? "hover" : disabled ? "disabled" : "",
									  )
								  : _variant === "text"
									  ? "transparent"
									  : color("neutral", "", "bg")
						};
						--label-color: ${
							_sentiment === "default"
								? color("neutral", "text", "weak", disabled ? "disabled" : "")
								: _variant === "fill"
								  ? color("neutral", "contrast-text")
								  : color(_sentiment, "", "", disabled ? "disabled" : "")
						};
						--border-color: ${
							_sentiment === "default"
								? "var(--control-border-medium-disabled)"
								: _variant === "fill"
								  ? `${color(_sentiment, "", "", disabled ? "disabled" : "")}`
								  : _variant === "text"
									  ? "transparent"
									  : `${color(_sentiment, "", "", disabled ? "disabled" : "")}`
						};

						--bg-color-hover: ${
							_sentiment === "default"
								? color("neutral", "", "bg-weak")
								: _variant === "fill"
								  ? color(_sentiment, "", "", "hover")
								  : color(_sentiment, "bg", "", "hover")
						};
						--label-color-hover: ${
							_variant !== "fill"
								? color(_sentiment, "", "", "hover")
								: color("neutral", "contrast-text")
						};
						--border-color-hover: ${
							_sentiment === "default"
								? color("neutral", "border", "medium", "")
								: _variant === "text"
								  ? "transparent"
								  : color(_sentiment, "", "", "hover")
						};

						--bg-color-active: ${
							_sentiment === "default"
								? color("neutral", "", "bg-weak")
								: _variant !== "fill"
								  ? _variant === "outline"
										? disabled
											? "transparent"
											: color(_sentiment, "", "", "highlight")
										: color(_sentiment, "", "", "highlight")
								  : color(_sentiment, "", "", "active")
						};
						--label-color-active: ${
							_variant !== "fill" && _variant !== "outline"
								? color(_sentiment, "", "", "hover")
								: _variant === "outline"
								  ? color(_sentiment, "", "", "")
								  : color("neutral", "contrast-text")
						};
						--border-color-active: ${
							_sentiment === "default"
								? color("neutral", "border", "medium", "")
								: _variant === "fill"
								  ? color(_sentiment, "", "", "active")
								  : _variant === "outline"
									  ? color(_sentiment, "", "", disabled ? "disabled" : "")
									  : "transparent"
						};
					}
				`);
			} else {
				const _variant =
					this.buttonGroup && !this.variant
						? "outline"
						: !this.variant
						  ? "fill"
						  : this.variant;
				this.sheet.replaceSync(`
					:host {
						${getCssRulesForSentimentButton({
							sentiment: sentiment || "interact",
							variant: _variant,
							disabled,
						})};
					}
				`);
			}
			addConstructedStyle(this.host.shadowRoot, this.sheet);

			/** icon */
			if (sentiment && sentiment !== "header") {
				const _variant =
					this.buttonGroup && !this.variant
						? "outline"
						: !this.variant
						  ? "fill"
						  : this.variant;
				this.sentimentSheet.replaceSync(`
					:host {
						${getCssRulesForSentimentButton({
							sentiment,
							variant: _variant,
							disabled,
							type: "icon",
						})};
					}
				`);
				addConstructedStyle(this.host.shadowRoot, this.sentimentSheet);
			}
		}

		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const { label, expanded, pressed, haspopup, controls, role } =
			this.aria || {};

		return (
			<Host>
				<button
					ref={(el) => {
						this.button = el;
					}}
					role={role || this.ariarole}
					part={part}
					class={btnCls}
					disabled={this.disabled}
					type={this.type}
					name={this.name}
					value={this.value}
					onBlur={this.handleBlur}
					onFocus={this.handleFocus}
					onPointerDown={this.handlePointerDown}
					onClick={this.handleClick}
					aria-disabled={loading || disabled ? "true" : "false"}
					aria-haspopup={haspopup || this.ariahaspopup}
					aria-describedby={this.tooltip ? this.tooltipId : null}
					aria-expanded={expanded || this.ariaexpanded}
					aria-label={label || ariaLabel}
					aria-pressed={pressed || this.ariapressed}
					aria-controls={controls || this.ariacontrols}
					tabindex={this.tabidx ? this.tabidx : this.disabled ? "-1" : "0"}
					data-testid="HbrButton-button"
				>
					{this.hasPrefix && (
						<span part="prefix" class={{ button__prefix: this.hasPrefix }}>
							<slot onSlotchange={this.handleSlotChange} name="prefix" />
						</span>
					)}
					<span
						part={`label${iconLabelButton ? " icon-label" : ""}`}
						class="button__label"
					>
						<slot onSlotchange={this.handleSlotChange} />
					</span>
					{this.hasSuffix && (
						<span part="suffix" class={{ button__suffix: this.hasSuffix }}>
							<slot onSlotchange={this.handleSlotChange} name="suffix" />
						</span>
					)}

					{this.caret && (
						<hbr-icon
							part="caret"
							class="button__caret"
							asset={customSystemIcons?.caret || caret}
						/>
					)}
					{this.loading && <hbr-spinner />}
				</button>
				<span id={this.tooltipId} hidden>
					{this.tooltip}
				</span>
			</Host>
		);
	}
}
