import { Component, Prop, h } from "@stencil/core";
import { loader } from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { internationalization } from "../../utils/i18n/translations";
import translations from "./i18n";

/**
 * @since 2.0
 * @status stable
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-spinner",
	styleUrl: "spinner.scss",
	shadow: true,
})
export class Spinner {
	/** The size of the spinner icon */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" | "extra-large";

	/** Flex direction of spinner container */
	@Prop({ reflect: true }) direction: "row" | "column" = "row";

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<span
				part="base"
				class={{
					spinner: true,
					[`spinner-direction-${this.direction}`]: true,
					...(this.size ? { [`spinner-size-${this.size}`]: true } : null),
				}}
				role="progressbar"
				aria-valuemin="0"
				aria-valuemax="100"
				aria-valuenow="50"
				aria-label={internationalization(translations, "loading")}
			>
				<div class="spinner-icon" part="icon">
					<slot name="icon">
						<hbr-icon asset={customSystemIcons?.loader || loader} />
					</slot>
				</div>
				<slot name="label" />
			</span>
		);
	}
}
